<script setup lang="ts">
import {onMounted,onBeforeUnmount,ref,watch} from 'vue'
import * as T from 'three'
import {OrbitControls} from 'three/addons/controls/OrbitControls.js'
import {box,makeDrone,makeScholar,makeTileAsset,tree} from '../three/models'
import type {RoomState} from '../types'
import content from '../content.json'
const props=defineProps<{state:RoomState}>()
const host=ref<HTMLDivElement>(),canvas=ref<HTMLCanvasElement>(),fallback=ref(false),labels=ref<{x:number;y:number;text:string;kind:string;hint?:string}[]>([])
let scene:T.Scene,camera:T.OrthographicCamera,renderer:T.WebGLRenderer,controls:OrbitControls,observer:ResizeObserver,frame=0,last=0,objects:T.Group,dead=false
let anchors:{position:T.Vector3;text:string;kind:string;hint?:string}[]=[],drones:T.Group[]=[]
const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches
function dispose(o:T.Object3D){o.traverse(v=>{if(v instanceof T.Mesh){v.geometry.dispose();for(const m of Array.isArray(v.material)?v.material:[v.material])m.dispose()}})}
function label(text:string,x:number,y:number,z:number,kind='detail',hint=text){anchors.push({text,hint,position:new T.Vector3(x,y,z),kind})}
function build(){if(!scene)return;if(objects){scene.remove(objects);dispose(objects)}objects=new T.Group();anchors=[];drones=[];scene.add(objects);box(objects,14,.18,10,0,-.15,0,0xe8e1d7);box(objects,.12,.07,9.7,0,0,0,0xd9d1c5)
 const players=Object.values(props.state.players);for(const [index,p]of players.entries()){const x=index?3.4:-3.4,theme=p.discipline==='civil'?0x6d9dcf:0xcd91af,decor=p.living.decor;box(objects,6.4,.035,8.9,x,-.035,0,index?0xf0e6ec:0xe5edf5);box(objects,6.3,1.9,.12,x,.85,-4.5,0xf8f1e5);box(objects,2,.12,.9,x,.75,-1.4,decor.includes('pink-desk')?0xcf98b1:decor.includes('blue-desk')?0x7da5cd:theme);for(const side of [-.8,.8])box(objects,.11,.8,.11,x+side,.35,-1.4,0x9d8c7a);box(objects,.5,.38,.055,x,.98,-1.65,0x53647b);box(objects,.43,.29,.018,x,1,-1.61,0xc6e0e6);box(objects,.45,.035,.19,x,.83,-1.23,0xefede5)
  const lead=makeScholar(p.discipline);lead.group.position.set(x,.04,-.4);lead.group.scale.setScalar(1.35);objects.add(lead.group);label(p.name+' · '+p.career.title,x,2.3,-3.9,'owner');
  const students=p.students.filter(s=>!s.graduatedAt);for(const [i,st]of students.entries()){const sx=x-1.4+(i%4)*.88,sz=.8+Math.floor(i/4)*.58;box(objects,.62,.06,.35,sx,.36,sz,0xd2c2a7);box(objects,.23,.18,.025,sx,.49,sz-.09,theme);const actor=makeScholar(p.discipline);actor.group.scale.setScalar(.58);actor.group.position.set(sx,.02,sz+.28);objects.add(actor.group);if(i<8)label(st.name,sx,.95,sz+.2,'student');}
  for(const [i,a]of p.assets.entries()){const sku=content.operations.catalog.find(d=>d.id===a.sku),ax=x-2.4+(i%2)*4.8,az=-3.25+Math.floor(i/2)*1.45;let model:T.Group;if(a.mode==='rental'){model=new T.Group();box(model,.5,.45,.45,0,.24,0,0xc9b695);box(model,.32,.06,.47,0,.3,0,theme)}else if(a.sku.includes('uav')){model=makeDrone();model.position.y=.6;drones.push(model)}else model=makeTileAsset('equipment',a.sku.includes('gpu')?16:a.sku.includes('robot')?12:22);model.scale.setScalar(.6);model.position.x=ax;model.position.z=az;objects.add(model);label((sku?.name||a.sku)+(a.mode==='rental'?' · 校内出租':''),ax,1.25,az,'asset');}
  if(decor.includes('plant')){const plant=tree(.8);plant.position.set(x+2,.02,3.8);objects.add(plant)}
  if(decor.includes('lamp')){box(objects,.06,.75,.06,x+.8,1.1,-1.4,0x9e8058);box(objects,.45,.08,.32,x+.7,1.5,-1.4,0xf0d79b)}
  if(decor.includes('coffee')){box(objects,.9,.65,.6,x+1.6,.3,3.7,0xc3a18a);for(const dx of [-.2,.15])box(objects,.16,.2,.16,x+1.6+dx,.75,3.7,index?0xdaa8b8:0x9fbada);label('奶茶与咖啡角',x+1.6,1.2,3.7)}
  if(decor.includes('sofa')){box(objects,1.3,.3,.65,x-1.4,.3,3.8,theme);box(objects,1.3,.4,.16,x-1.4,.55,4.05,theme)}
  const memories=p.living.memories.slice(-5);for(const [i,m]of memories.entries()){box(objects,.88,.62,.065,x-2.3+i*1.15,1.2,-4.36,0xc7aa78);box(objects,.76,.5,.025,x-2.3+i*1.15,1.2,-4.3,0xfffdf2);label(m.title.includes('论文')?'论文':m.title.includes('专利')?'专利':m.title.includes('示范')?'示范':m.title.includes('试点')?'试点':m.title.includes('毕业')?'毕业':m.title.slice(0,3),x-2.3+i*1.15,1.7,-4.3,'memory',m.title);}
  if(decor.includes('display')){box(objects,1.8,.7,.5,x,.36,4.1,0x9c8871);for(let i=0;i<3;i++){box(objects,.14,.3+i*.06,.14,x-.5+i*.5,.9,4.1,0xd5b56f)}}
  for(const [i,f]of p.institute.faculty.entries()){const actor=makeScholar(p.discipline);actor.group.scale.setScalar(.85);actor.group.position.set(x-1.9+i*.86,.05,-2.8);objects.add(actor.group);label(f.name,x-1.9+i*.86,1.2,-2.8,'faculty',f.rank+' · '+f.name+'老师')}
  if(p.institute.workstation){box(objects,1.4,.08,.8,x,.25,-3.65,0xd4b978);box(objects,.8,.55,.5,x,.55,-3.65,0xf2e7c7);label('院士工作站',x,1.2,-3.65,'memory')}
  const demos=p.living.transfers.filter(t=>t.route==='demo'&&t.status==='completed');for(const [i,t]of demos.slice(-2).entries()){box(objects,.6,.45,.45,x+1.7+i*.7,.26,-2.3,0x9fb5b9);box(objects,.5,.08,.5,x+1.7+i*.7,.6,-2.3,theme);label('示范展台',x+1.7+i*.7,1,-2.3,'memory')}
  const gift=p.living.gifts.find(g=>g.to===p.id&&!g.openedAt);if(gift){box(objects,.3,.25,.26,x+.55,.95,-1.2,index?0xb991b5:0x7aa8ca);box(objects,.05,.27,.28,x+.55,.95,-1.2,0xf0d5a2);label('桌上有一份心意',x+.55,1.5,-1.2,'gift')}
  if(p.living.notes.some(n=>n.to===p.id)||players.some(v=>v.living.notes.some(n=>n.to===p.id)))box(objects,.3,.035,.2,x-.6,.84,-1.2,0xf1dd9d);
 }
}
function fit(){if(!host.value||!renderer)return;const w=host.value.clientWidth,h=host.value.clientHeight,ratio=w/h,view=Math.max(13,17/ratio);camera.left=-view*ratio/2;camera.right=view*ratio/2;camera.top=view/2;camera.bottom=-view/2;camera.updateProjectionMatrix();renderer.setSize(w,h,false)}
function draw(time:number){if(dead)return;frame=requestAnimationFrame(draw);if(document.hidden||time-last<40)return;last=time;if(!reduced)for(const [i,d]of drones.entries())d.position.y=.6+Math.sin(time*.001+i)*.06;controls.update();const r=host.value?.getBoundingClientRect();if(r)labels.value=anchors.map(a=>{const p=a.position.clone().project(camera);return{x:(p.x*.5+.5)*r.width,y:(-.5*p.y+.5)*r.height,text:a.text,kind:a.kind,hint:a.hint}});renderer.render(scene,camera)}
function zoom(n:number){if(!camera)return;camera.zoom=T.MathUtils.clamp(camera.zoom*n,.7,1.8);camera.updateProjectionMatrix()}
onMounted(()=>{try{scene=new T.Scene();scene.background=new T.Color(0xf0ece5);camera=new T.OrthographicCamera(-10,10,7,-7,.1,100);camera.position.set(1,15,14);camera.lookAt(0,0,0);renderer=new T.WebGLRenderer({canvas:canvas.value,antialias:true,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.toneMapping=T.ACESFilmicToneMapping;scene.add(new T.HemisphereLight(0xfffaf1,0x91a5b0,2));const sun=new T.DirectionalLight(0xfff4dd,2);sun.position.set(-4,10,5);scene.add(sun);controls=new OrbitControls(camera,canvas.value);controls.enablePan=false;controls.enableDamping=true;controls.minPolarAngle=.4;controls.maxPolarAngle=1.15;controls.minZoom=.7;controls.maxZoom=1.8;build();fit();observer=new ResizeObserver(fit);observer.observe(host.value!);frame=requestAnimationFrame(draw)}catch{fallback.value=true}})
watch(()=>props.state.version,build)
onBeforeUnmount(()=>{dead=true;cancelAnimationFrame(frame);observer?.disconnect();controls?.dispose();if(scene)dispose(scene);renderer?.dispose()})
</script>
<template><div class="lab-interior" ref="host"><template v-if="!fallback"><canvas ref="canvas" aria-label="可旋转的双人三维实验室，展示设备、师生工位与成果纪念"/><div class="interior-labels" aria-hidden="true"><span v-for="(l,i) in labels" :key="i" :class="l.kind" :title="l.hint" :style="{left:l.x+'px',top:l.y+'px'}">{{ l.text }}</span></div><div class="interior-toolbar"><span>拖动转一转 · 布置与资产会自动摆进实景</span><button aria-label="缩小实验室" @click="zoom(.85)">−</button><button aria-label="放大实验室" @click="zoom(1.15)">+</button></div></template><div v-else class="interior-fallback"><article v-for="p in state.players" :key="p.id"><h3>{{ p.name }}的实验室</h3><p>{{ p.students.filter(s=>!s.graduatedAt).length }} 位同学 · {{ p.institute.faculty.length }} 位教师</p><ul><li v-for="a in p.assets" :key="a.id">{{ content.operations.catalog.find(d=>d.id===a.sku)?.name }} · {{ a.mode==='rental'?'出租给学校':'科研使用' }}</li><li v-for="m in p.living.memories" :key="m.id">{{ m.title }}</li></ul></article></div></div></template>
